  if(n.content||n.mask||l.kind!=LayerKind::Fill||l.instance)fail("Material source requires a fill layer");if(!resources.asset)fail("Resource resolver is unavailable");const auto a=resources.asset(uuid(p["resource"]),true);if(!a.material||a.smart_material||a.fill_preset||a.projection_weave)fail("Choose a native uniform PBR material");l.values=*a.material;l.fill.texture.reset();l.fill.channel_textures.reset();l.fill.atom=false;l.fill.material_resource=a.id.toString(QUuid::WithoutBraces).toStdString();return info(document,node(document,p["reference"].toObject()),resources);
